import random

def test_r(r, num_elements=10):
    # Using 10 elements instead of 100 for speed,
    # but we can increase it if needed.
    # The problem says "regardless of the numbers on the blackboard",
    # so if it fails for 10, it fails for 100.
    # Also, if it works for small sets, it's more likely to work for larger sets.
    # However, the problem says "100 distinct real numbers".
    # Let's use a small set and check.
    a = [random.uniform(-100, 100) for _ in range(num_elements)]
    # Ensure they are distinct
    if len(set(a)) != num_elements:
        return test_r(r, num_elements)

    p1 = set()
    for i in range(num_elements):
        for j in range(num_elements):
            p1.add(a[i] - a[j])

    p2 = set()
    for p in p1:
        for q in p1:
            p2.add(3 * p * q * r)

    p3 = set()
    # This part is O(|P1|^4), which is too slow.
    # |P1| can be up to 10*9 = 90. 90^4 is ~65 million.
    # Maybe we can optimize p3 construction.
    # P3 = {x^2 + y^2 - z^2 - w^2} = {x^2 - z^2} + {y^2 - w^2}
    diff_sq = set()
    for x in p1:
        for z in p1:
            diff_sq.add(x*x - z*z)

    for ds1 in diff_sq:
        for ds2 in diff_sq:
            p3.add(ds1 + ds2)

    for val in p2:
        # Using a small epsilon for float comparison
        found = False
        for p3_val in p3:
            if abs(val - p3_val) < 1e-7:
                found = True
                break
        if not found:
            return False, val
    return True, None

