import random

def test_r(r, num_elements=15, num_trials=10):
    for _ in range(num_trials):
        a = [random.uniform(-10, 10) for _ in range(num_elements)]
        if len(set(a)) != num_elements:
            continue

        p1 = sorted(list(set([a[i] - a[j] for i in range(num_elements) for j in range(num_elements)])))
        p2 = [3 * p * q * r for p in p1 for q in p1]
        diff_sq = sorted([x*x - z*z for x in p1 for z in p1])

        for v in p2:
            found = False
            left = 0
            right = len(diff_sq) - 1
            while left <= right:
                s = diff_sq[left] + diff_sq[right]
                if abs(s - v) < 1e-7:
                    found = True
                    break
                elif s < v:
                    left += 1
                else:
                    right -= 1
            if not found:
                return False, v
    return True, None

