def test_r_large_n_random_pq(r, n=30, num_trials=5):
    for _ in range(num_trials):
        a = [random.uniform(-100, 100) for _ in range(n)]
        if len(set(a)) != n:
            continue

        p1 = sorted(list(set([a[i] - a[j] for i in range(n) for j in range(n)])))
        diff_sq_list = sorted(list(set([x*x - z*z for x in p1 for z in p1])))

        for _ in range(100):
            p = random.choice(p1)
            q = random.choice(p1)
            v = 3 * p * q * r
            found = False
            # To speed this up, only check a subset of diff_sq_list?
            # No, we need to check all. But we can use a set for O(1) check.
            # Since we have floats, let's round them.
            diff_sq_set = {round(ds, 6) for ds in diff_sq_list}
            for ds in diff_sq_list:
                if round(v - ds, 6) in diff_sq_set:
                    found = True
                    break
            if not found:
                return False
    return True

